const SHARED_TRIGGER_UPLOAD_DEADLINE: Duration = Duration::from_secs(25);
static NEXT_WORKFLOW_OWNER: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

fn next_direct_act_owner() -> String {
    let sequence = NEXT_WORKFLOW_OWNER.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    format!("act:{}:{sequence}", std::process::id())
}
static NEXT_SKILL_EXAMPLE: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(1);

async fn measured_receipt(
    operation: impl Future<Output = Result<Json<Value>, rmcp::ErrorData>>,
) -> Result<Json<Value>, rmcp::ErrorData> {
    let budget = crate::v3::CommandBudget::interactive_default();
    let wall_limit = Duration::from_millis(budget.max_wall_ms);
    let (result, mut metrics) = controlla_browser::scheduler::telemetry::collect_operation_metrics(
        controlla_browser::scheduler::telemetry::with_browser_command_budget(
            budget.max_browser_commands as u64,
            budget.max_cdp_commands as u64,
            wall_limit,
            operation,
        ),
    )
    .await;
    result.map(|Json(mut receipt)| {
        let serialization_started = std::time::Instant::now();
        let observation_packets = u64::from(contains_returned_page_evidence(&receipt));
        metrics.returned_observation_packets = observation_packets;
        attach_observation_boundary(&mut receipt, observation_packets);
        attach_operation_costs(&mut receipt, &metrics);
        metrics.phases.serialization_us = serialization_started
            .elapsed()
            .as_micros()
            .min(u64::MAX as u128) as u64;
        receipt["metrics"] = serde_json::to_value(&metrics).unwrap_or(Value::Null);
        Json(receipt)
    })
}

/// Count one bounded observation packet only when page evidence is present in
/// the structured payload actually being returned by this MCP operation.
/// This does not claim that an external model read or acted on that packet.
fn contains_returned_page_evidence(value: &Value) -> bool {
    const EVIDENCE_KEYS: &[&str] = &[
        "items",
        "records",
        "matches",
        "entries",
        "history_delta",
        "observation",
        "observed",
        "selected",
        "visual_probe",
        "visual_evidence",
        "merged_evidence",
    ];
    fn visit(value: &Value) -> bool {
        match value {
            Value::Object(object) => {
                if object.get("visual_content_attached") == Some(&Value::Bool(true)) {
                    return true;
                }
                object.iter().any(|(key, child)| {
                    EVIDENCE_KEYS.contains(&key.as_str()) && !child.is_null()
                        || (key == "metrics"
                            && child["observation_bytes"].as_u64().unwrap_or(0) > 0)
                        || visit(child)
                })
            }
            Value::Array(items) => items.iter().any(visit),
            _ => false,
        }
    }
    visit(value)
}

fn attach_observation_boundary(value: &mut Value, count: u64) {
    value["observation_boundary"] = json!({
        "returned_observation_packets":count,
        "count_source":"structured_mcp_response_at_return_boundary",
        "count_complete":true,
        "external_model_inspection":Value::Null,
        "external_model_telemetry":"outside_mcp_process"
    });
    if value["metrics"].is_object() {
        value["metrics"]["returned_observation_packets"] = json!(count);
    }
    for route_key in ["execution_route", "route_receipt"] {
        if value[route_key].is_object() {
            value[route_key]["actual_cost"]["returned_observation_packets"] = json!(count);
            value[route_key]["actual_cost"]["returned_observation_count_source"] =
                json!("structured_mcp_response_at_return_boundary");
        }
    }
}

fn attach_operation_costs(
    receipt: &mut Value,
    metrics: &controlla_browser::scheduler::telemetry::OperationMetrics,
) {
    for route_key in ["execution_route", "route_receipt"] {
        if receipt.get(route_key).is_some_and(Value::is_object) {
            receipt[route_key]["actual_cost"]["cdp_commands"] = json!(metrics.cdp_commands);
            receipt[route_key]["actual_cost"]["host_round_trips"] = json!(metrics.host_round_trips);
            receipt[route_key]["actual_cost"]["observation_bytes"] =
                json!(metrics.observation_bytes);
            receipt[route_key]["actual_cost"]["browser_command_budget_used"] =
                json!(metrics.browser_commands_used);
            receipt[route_key]["actual_cost"]["cdp_measurement_partial"] =
                json!(metrics.cdp_commands_partial);
        }
    }
}

fn open_workflow_route_receipt(
    elapsed_ms: u64,
    origin: &str,
    task_size: &str,
    cold_browser: bool,
    workflow: &Value,
) -> Value {
    let verified = workflow["status"] == "completed"
        && workflow["receipts"].as_array().is_some_and(|receipts| {
            !receipts.is_empty() && receipts.iter().all(|receipt| receipt["verified"] == true)
        });
    json!({
        "tier":"semantic_program",
        "route_kind":"caller_supplied_open_steps",
        "reason":"the caller supplied a bounded deterministic workflow; no alternate plan was selected",
        "verification":if verified {"passed"} else {"inconclusive"},
        "cost_policy":{"kind":"measured_only","route_selection":"not_applicable_to_fixed_steps"},
        "cost_cohort":{"origin_key":origin,"intent":"open_steps_workflow",
            "warmth":if cold_browser {"cold_browser"} else {"warm_browser_seen_site"},"task_size":task_size},
        "actual_cost":{"browser_call_elapsed_ms":elapsed_ms,
            "measurement_scope":"mcp_received_to_workflow_result",
            "prompt_send_to_verified_ms":null,"external_model_calls":null,
            "reported_internal_model_calls":0}
    })
}

fn background_window_focus_invariant(result: &Value) -> bool {
    result["created_background_window"] == true && result["window_focused"] == false
}

fn selected_automation_window_invariant(result: &Value, expected_window_id: u64) -> bool {
    result["window_id"].as_u64() == Some(expected_window_id)
        && result["window_focused"] == false
        && result["tab_active"] == true
}

fn foreground_open_invariant(result: &Value) -> bool {
    result["tab_active"] == true && result["window_focused"] == true
}

fn apply_foreground_open_presentation_gate(result: &mut Value) -> bool {
    let invariant = foreground_open_invariant(result);
    result["foreground_presentation_invariant"] = json!(invariant);
    if !invariant {
        result["status"] = json!("incomplete");
        result["reason_code"] = json!("foreground_presentation_not_verified");
        result["dispatch_may_have_occurred"] = json!(true);
        result["presentation_verified"] = json!(false);
        result["workflow_steps_dispatched"] = json!(false);
        result["next_action"] = json!(
            "the tab was opened but active-tab or focused-window presentation was not confirmed; inspect it before continuing; workflow steps were not dispatched"
        );
        return false;
    }
    result["presentation_verified"] = json!(true);
    true
}

