    #[test]
    fn act_value_contract_accepts_value_actions_and_preserves_password_limits() {
        for action in ["fill", "secure_fill", "type", "select", "slider"] {
            assert!(
                super::validate_act_value_contract(action, Some("value"), None).is_ok(),
                "{action} should accept its value parameter"
            );
        }
        assert!(super::validate_act_value_contract("click", Some("value"), None).is_err());
        assert!(super::validate_act_value_contract("select", None, None).is_err());
        assert!(super::validate_act_value_contract("type", Some("text"), Some(true)).is_err());
        assert!(super::validate_act_value_contract("fill", Some("text"), Some(true)).is_ok());
        assert!(super::validate_act_value_contract("secure_fill", Some(""), Some(true)).is_ok());
    }

    #[test]
    fn omitted_click_outcomes_are_inferred_only_from_fresh_semantic_state() {
        assert!(matches!(
            super::infer_click_outcome(&json!({"tag":"a","href":"https://example.test/"})),
            Some(BrowserClickOutcome::Navigation { url: None })
        ));
        assert!(matches!(
            super::infer_click_outcome(&json!({"role":"button","expanded":false})),
            Some(BrowserClickOutcome::Expanded { selector: None })
        ));
        assert!(matches!(
            super::infer_click_outcome(&json!({"role":"checkbox","selected":false})),
            Some(BrowserClickOutcome::Selected { selector: None })
        ));
        assert!(matches!(
            super::infer_click_outcome(&json!({"role":"button","name":"Save"})),
            Some(BrowserClickOutcome::Focused)
        ));
        assert!(super::infer_click_outcome(&json!({"role":"generic","name":"Save"})).is_none());
    }

    #[test]
    fn key_chord_dispatches_modifiers_then_key_and_releases_in_reverse_order() {
        let events = super::key_chord_events("Control+Shift+A").unwrap();
        assert_eq!(events.len(), 5);
        assert_eq!(
            events[0].0,
            json!({"type":"keyDown","key":"Control","modifiers":2})
        );
        assert_eq!(
            events[1].0,
            json!({"type":"keyDown","key":"Shift","modifiers":10})
        );
        assert_eq!(
            events[2].0,
            json!({"type":"keyDown","key":"A","modifiers":10})
        );
        assert_eq!(
            events[3].0,
            json!({"type":"keyUp","key":"Shift","modifiers":2})
        );
        assert_eq!(
            events[4].0,
            json!({"type":"keyUp","key":"Control","modifiers":0})
        );
        assert_eq!(
            events[2].1,
            Some(json!({"type":"keyUp","key":"A","modifiers":10}))
        );
    }

    #[test]
    fn key_chord_rejects_ambiguous_modifier_sequences_before_dispatch() {
        assert!(super::key_chord_events("Control++A").is_err());
        assert!(super::key_chord_events("Control+Ctrl+A").is_err());
        assert!(super::key_chord_events("Super+A").is_err());
        assert!(super::key_chord_events("Control+").is_err());
        assert_eq!(super::key_chord_events("Enter").unwrap().len(), 1);
    }

    #[test]
    fn app_specific_adapter_references_resolve_from_fresh_workflow_variables() {
        let vars = [
            ("slide".to_owned(), "@c12".to_owned()),
            ("account".to_owned(), "@c13".to_owned()),
            ("class".to_owned(), "@c14".to_owned()),
            ("assignment".to_owned(), "@c15".to_owned()),
            ("attachment".to_owned(), "@c16".to_owned()),
        ]
        .into_iter()
        .collect();
        let canva = super::BrowserPredicate::AppSpecific {
            adapter: "canva_slide_manifest_v1".into(),
            predicate: json!({"version":1,"slides":[{"reference":"$slide"}]}),
        };
        let resolved =
            super::resolve_workflow_predicate(canva, &vars, &Default::default()).unwrap();
        assert_eq!(
            serde_json::to_value(resolved).unwrap(),
            json!({"kind":"app_specific","adapter":"canva_slide_manifest_v1","predicate":{"version":1,"slides":[{"reference":"@c12"}]}})
        );
        let classroom = super::BrowserPredicate::AppSpecific {
            adapter: "google_classroom_attachment_v1".into(),
            predicate: json!({"version":1,"account":{"reference":"$account"},"class":{"reference":"$class"},"assignment":{"reference":"$assignment"},"attachment":{"reference":"$attachment"}}),
        };
        let resolved =
            super::resolve_workflow_predicate(classroom, &vars, &Default::default()).unwrap();
        assert_eq!(
            serde_json::to_value(resolved).unwrap(),
            json!({"kind":"app_specific","adapter":"google_classroom_attachment_v1","predicate":{"version":1,"account":{"reference":"@c13"},"class":{"reference":"@c14"},"assignment":{"reference":"@c15"},"attachment":{"reference":"@c16"}}})
        );
        let drive_attachment = super::BrowserPredicate::AppSpecific {
            adapter: "google_drive_attachment_v1".into(),
            predicate: json!({"version":1,"url":"https://classroom.google.com/c/class/a/assignment",
                "account":{"reference":"$account"},"attachment":{"reference":"$attachment","name":"lesson.pdf","size":1234,"role":"attachment"}}),
        };
        let resolved =
            super::resolve_workflow_predicate(drive_attachment, &vars, &Default::default())
                .unwrap();
        let resolved = serde_json::to_value(resolved).unwrap();
        assert_eq!(resolved["predicate"]["account"]["reference"], "@c13");
        assert_eq!(resolved["predicate"]["attachment"]["reference"], "@c16");
    }

