    #[tokio::test]
    async fn readiness_error_releases_a_cold_session() {
        let app = AppV3::new(super::super::AppV2::new(super::super::App::default()));
        app.browser_modes.lock().await.insert(
            "missing-cold-session".into(),
            crate::v3::BrowserMode::Background,
        );
        let error = app
            .wait_for_open_readiness_or_release(
                "missing-cold-session",
                "missing-tab",
                &V3ReadyWhen::Selector {
                    selector: "main".into(),
                },
                true,
            )
            .await
            .unwrap_err();
        assert!(error.to_string().contains("unknown shared session"));
        assert!(
            !app.browser_modes
                .lock()
                .await
                .contains_key("missing-cold-session")
        );
    }

